package kfc.ui;
import kfc.database;import kfc.service.*;import kfc.dao.TaiKhoanDAO;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.io.*;import java.math.BigDecimal;import java.nio.file.*;import java.sql.*;import java.util.ArrayList;import java.util.Arrays;import java.util.List;
/** Mở rộng bằng các tab; không thay layout các màn hình cũ. */
public final class NghiepVuPanel extends JPanel {
 private final JTabbedPane tabs=new JTabbedPane();
 @FunctionalInterface interface Action {void run() throws Exception;}
 private void run(Action a){try{PhienQuanLy.yeuCauDangNhap();a.run();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Không thực hiện được",JOptionPane.ERROR_MESSAGE);}}
 private JButton button(String name,Action a){JButton b=new JButton(name);b.addActionListener(e->run(a));return b;}
 private String input(String label,String def){String s=JOptionPane.showInputDialog(this,label,def);if(s==null)throw new IllegalArgumentException("Đã hủy thao tác");return s.trim();}
 private String required(String label,String def){String s=input(label,def);if(s.isEmpty())throw new IllegalArgumentException("Không được bỏ trống: "+label);return s;}
 private String choose(String label,String... values){Object s=JOptionPane.showInputDialog(this,label,"Chọn",JOptionPane.QUESTION_MESSAGE,null,values,values[0]);if(s==null)throw new IllegalArgumentException("Đã hủy");return s.toString();}
 private boolean confirm(String s){return JOptionPane.showConfirmDialog(this,s,"Xác nhận",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
 private boolean role(String... roles){return PhienQuanLy.coVaiTro(roles);}
 private int update(String sql,Object... args)throws SQLException{try(Connection c=database.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p.executeUpdate();}}
 private class View extends JPanel {
  final JTable table=new JTable();final JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));final String sql; final Object[] params;
  View(String s,Object... p){super(new BorderLayout(8,8));sql=s;params=p;table.setAutoCreateRowSorter(true);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);add(tools,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);addBtn("Làm mới",this::load);}
  void addBtn(String s,Action a){tools.add(button(s,a));}
  void load()throws SQLException{try(Connection c=database.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<params.length;i++)p.setObject(i+1,params[i]);try(ResultSet r=p.executeQuery()){ResultSetMetaData md=r.getMetaData();String[] cols=new String[md.getColumnCount()];for(int i=0;i<cols.length;i++)cols[i]=md.getColumnLabel(i+1);DefaultTableModel m=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;} public Class<?> getColumnClass(int col){for(int r=0;r<getRowCount();r++){Object v=getValueAt(r,col);if(v!=null)return v.getClass();}return Object.class;}};while(r.next()){Object[] row=new Object[cols.length];for(int i=0;i<cols.length;i++)row[i]=r.getObject(i+1);m.addRow(row);}table.setModel(m);}}}
  Object value(int col){int r=table.getSelectedRow();if(r<0)throw new IllegalArgumentException("Chọn một dòng");return table.getModel().getValueAt(table.convertRowIndexToModel(r),col);}
  String str(int col){return value(col)==null?"":value(col).toString();}
  int id(){return ((Number)value(0)).intValue();}
 }
 private void add(String title,View v){tabs.addTab(title,v);}
 public NghiepVuPanel(){super(new BorderLayout());PhienQuanLy.yeuCauDangNhap();add(tabs);if(role("ADMIN","THU_NGAN","BEP"))orders();if(role("ADMIN","THU_NGAN")){customers();dashboard();}if(role("ADMIN")){staff();categories();}if(role("ADMIN","KHO")){suppliers();receipts();stock();}tabs.addChangeListener(e->refresh());refresh();}
 public void refresh(){Component c=tabs.getSelectedComponent();if(c instanceof View)run(((View)c)::load);}
 private void orders(){String filter=role("ADMIN","THU_NGAN")?"":" WHERE TrangThai IN ('CHO_CHE_BIEN','DANG_CHE_BIEN','SAN_SANG')";View v=new View("SELECT MaHD,NgayLap,TongTien,PhuongThuc,TrangThai,TrangThaiTT,HinhThuc,TienNhan,TienThua,MaGiaoDich FROM hoa_don"+filter+" ORDER BY MaHD DESC LIMIT 500");
  v.addBtn("Chi tiết",()->{JTextArea a=new JTextArea(new kfc.dao.HoaDonDAO().noiDungHoaDon(v.id()),18,45);a.setEditable(false);JOptionPane.showMessageDialog(this,new JScrollPane(a));});
  if(role("ADMIN","THU_NGAN")){v.addBtn("Thu tiền",()->{int id=v.id();String method=v.str(3);BigDecimal total=new BigDecimal(v.str(2));BigDecimal received=new BigDecimal(required("Tiền thực nhận",total.toPlainString()));String code=method.equals("CHUYEN_KHOAN")?required("Mã giao dịch đã kiểm tra tại ngân hàng",""):null;if(!confirm("Xác nhận thực nhận "+received+" đ? Tiền thừa: "+received.subtract(total)+" đ"))return;DonHangService.thanhToan(id,received,code);v.load();});v.addBtn("Giao món",()->{DonHangService.tienTrinh(v.id(),"HOAN_THANH");v.load();});v.addBtn("Hủy đơn",()->{int id=v.id();String reason=required("Lý do hủy","");boolean paid=v.str(5).equals("DA_THANH_TOAN");boolean refund=paid&&role("ADMIN")&&confirm("Đã hoàn tiền thực tế cho khách?");if(paid&&!refund)return;boolean hoan=Arrays.asList("CHO_THANH_TOAN","CHO_CHE_BIEN").contains(v.str(4))&&confirm("Nguyên liệu chưa chế biến — hoàn kho?");if(confirm("Hủy đơn HD"+id+"?")){DonHangService.huy(id,hoan,refund,reason);v.load();}});}
  if(role("ADMIN","BEP")){v.addBtn("Bắt đầu bếp",()->{DonHangService.tienTrinh(v.id(),"DANG_CHE_BIEN");v.load();});v.addBtn("Sẵn sàng",()->{DonHangService.tienTrinh(v.id(),"SAN_SANG");v.load();});}add("Đơn hàng / bếp",v);
 }
 private void customers(){View v=new View("SELECT MaKH,TenKH,SDT FROM khach_hang ORDER BY MaKH DESC");v.addBtn("Thêm",()->{PhienQuanLy.yeuCauVaiTro("ADMIN","THU_NGAN");String name=required("Tên khách hàng","");String phone=phone("");update("INSERT INTO khach_hang(TenKH,SDT) VALUES(?,?)",name,phone);v.load();});v.addBtn("Sửa",()->{int id=v.id();update("UPDATE khach_hang SET TenKH=?,SDT=? WHERE MaKH=?",required("Tên",v.str(1)),phone(v.str(2)),id);v.load();});v.addBtn("Lịch sử mua",()->{View history=new View("SELECT MaHD,NgayLap,TongTien,TrangThaiTT FROM hoa_don WHERE MaKH=? ORDER BY MaHD DESC",v.id());history.load();history.setPreferredSize(new Dimension(650,300));JOptionPane.showMessageDialog(this,history);});add("Khách hàng",v);}
 private String phone(String def){String p=required("SĐT (10 số)",def);if(!p.matches("0[0-9]{9}"))throw new IllegalArgumentException("SĐT không hợp lệ");return p;}
 private String password()throws Exception{JPasswordField p=new JPasswordField(20);if(JOptionPane.showConfirmDialog(this,p,"Mật khẩu mới (ít nhất 10 ký tự)",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)throw new IllegalArgumentException("Đã hủy");char[] chars=p.getPassword();try{return TaiKhoanDAO.bamMatKhau(chars);}finally{Arrays.fill(chars,'\0');}}
 private void staff(){View v=new View("SELECT hoten AS TaiKhoan,TenNV,SDT,VaiTro,HoatDong FROM `user` ORDER BY hoten");v.addBtn("Tạo nhân viên",()->{PhienQuanLy.yeuCauVaiTro("ADMIN");String u=required("Tên đăng nhập","");if(!u.matches("[A-Za-z0-9_.-]{3,80}"))throw new IllegalArgumentException("Tên đăng nhập 3–80 ký tự ASCII");String name=required("Họ tên","");String ph=phone("");String role=choose("Vai trò","THU_NGAN","BEP","KHO","ADMIN");update("INSERT INTO `user`(hoten,mk,TenNV,SDT,VaiTro) VALUES(?,?,?,?,?)",u,password(),name,ph,role);v.load();});v.addBtn("Sửa thông tin",()->{PhienQuanLy.yeuCauVaiTro("ADMIN");String u=v.str(0);update("UPDATE `user` SET TenNV=?,SDT=? WHERE hoten=?",required("Tên",v.str(1)),phone(v.str(2)),u);v.load();});v.addBtn("Đổi quyền",()->{String u=v.str(0);if(u.equalsIgnoreCase(PhienQuanLy.taiKhoan()))throw new IllegalArgumentException("Không tự đổi quyền");update("UPDATE `user` SET VaiTro=? WHERE hoten=?",choose("Vai trò","THU_NGAN","BEP","KHO","ADMIN"),u);v.load();});v.addBtn("Khóa / mở",()->{String u=v.str(0);if(u.equalsIgnoreCase(PhienQuanLy.taiKhoan()))throw new IllegalArgumentException("Không tự khóa");update("UPDATE `user` SET HoatDong=NOT HoatDong WHERE hoten=?",u);v.load();});v.addBtn("Đặt lại mật khẩu",()->{String u=v.str(0);update("UPDATE `user` SET mk=? WHERE hoten=?",password(),u);v.load();});add("Nhân viên",v);}
 private void categories(){View dm=new View("SELECT TenDM FROM danh_muc ORDER BY TenDM");dm.addBtn("Thêm danh mục",()->{update("INSERT INTO danh_muc VALUES(?)",required("Tên danh mục",""));dm.load();});dm.addBtn("Xóa danh mục trống",()->{if(confirm("Xóa danh mục chưa dùng?")){update("DELETE FROM danh_muc WHERE TenDM=?",dm.str(0));dm.load();}});add("Danh mục",dm);View v=new View("SELECT MaMon,TenMon,DanhMuc,HinhAnh FROM monan ORDER BY MaMon");v.addBtn("Gán danh mục",()->{String ma=v.str(0);List<String> names=new ArrayList<>();try(ResultSet r=database.query("SELECT TenDM FROM danh_muc ORDER BY TenDM")){while(r.next())names.add(r.getString(1));}if(names.isEmpty())throw new IllegalArgumentException("Tạo danh mục trước");update("UPDATE monan SET DanhMuc=? WHERE MaMon=?",choose("Danh mục",names.toArray(new String[0])),ma);v.load();});v.addBtn("Chọn ảnh",()->{String ma=v.str(0);JFileChooser fc=new JFileChooser();fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Ảnh PNG/JPG","png","jpg","jpeg"));if(fc.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;File f=fc.getSelectedFile();if(f.length()>10_000_000)throw new IllegalArgumentException("Ảnh tối đa 10 MB");java.awt.image.BufferedImage image=javax.imageio.ImageIO.read(f);if(image==null)throw new IllegalArgumentException("Ảnh không hợp lệ");Path dir=Paths.get("data","images");Files.createDirectories(dir);Path dest=dir.resolve(java.util.UUID.randomUUID()+".png");javax.imageio.ImageIO.write(image,"png",dest.toFile());update("UPDATE monan SET HinhAnh=? WHERE MaMon=?",dest.toString(),ma);v.load();});v.addBtn("Bỏ ảnh",()->{update("UPDATE monan SET HinhAnh=NULL WHERE MaMon=?",v.str(0));v.load();});add("Ảnh món",v);}
 private void suppliers(){View v=new View("SELECT MaNCC,TenNCC,SDT,DiaChi FROM nha_cung_cap ORDER BY MaNCC");v.addBtn("Thêm",()->{update("INSERT INTO nha_cung_cap VALUES(?,?,?,?)",required("Mã NCC",""),required("Tên NCC",""),input("SĐT",""),input("Địa chỉ",""));v.load();});v.addBtn("Sửa",()->{String id=v.str(0);update("UPDATE nha_cung_cap SET TenNCC=?,SDT=?,DiaChi=? WHERE MaNCC=?",required("Tên NCC",v.str(1)),input("SĐT",v.str(2)),input("Địa chỉ",v.str(3)),id);v.load();});v.addBtn("Xóa NCC chưa sử dụng",()->{if(confirm("Xóa nhà cung cấp?")){update("DELETE FROM nha_cung_cap WHERE MaNCC=?",v.str(0));v.load();}});add("Nhà cung cấp",v);}
 private void receipts(){View v=new View("SELECT p.MaPN,p.NgayNhap,p.MaNCC,p.NguoiNhap, SUM(c.SoLuong*c.DonGia) AS TongChi FROM phieu_nhap p JOIN chi_tiet_phieu_nhap c ON p.MaPN=c.MaPN GROUP BY p.MaPN,p.NgayNhap,p.MaNCC,p.NguoiNhap ORDER BY p.MaPN DESC");v.addBtn("Lập phiếu nhập",()->{List<String> names=new ArrayList<>();try(ResultSet r=database.query("SELECT MaNCC FROM nha_cung_cap ORDER BY MaNCC")){while(r.next())names.add(r.getString(1));}if(names.isEmpty())throw new IllegalArgumentException("Tạo NCC trước");String ncc=choose("Nhà cung cấp",names.toArray(new String[0]));JTextArea lines=new JTextArea(8,32);JPanel p=new JPanel(new BorderLayout());p.add(new JLabel("Mỗi dòng: Mã NL; số lượng; đơn giá (dùng dấu chấm thập phân)"),BorderLayout.NORTH);p.add(new JScrollPane(lines));if(JOptionPane.showConfirmDialog(this,p,"Phiếu nhập",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;List<StockExtra.Line> data=new ArrayList<>();for(String line:lines.getText().split("\\R")){if(line.trim().isEmpty())continue;String[] a=line.split(";",-1);if(a.length!=3)throw new IllegalArgumentException("Dòng không hợp lệ: "+line);data.add(new StockExtra.Line(a[0].trim(),new BigDecimal(a[1].trim()),new BigDecimal(a[2].trim())));}StockExtra.nhap(ncc,data);v.load();});v.addBtn("Chi tiết phiếu",()->{View d=new View("SELECT MaNL,SoLuong,DonGia,SoLuong*DonGia AS ThanhTien FROM chi_tiet_phieu_nhap WHERE MaPN=?",v.id());d.load();d.setPreferredSize(new Dimension(600,320));JOptionPane.showMessageDialog(this,d);});add("Phiếu nhập",v);}
 private void stock(){View v=new View("SELECT MaNL,TenNL,DonVi,SoLuongTon,TonToiThieu,CASE WHEN SoLuongTon<=TonToiThieu THEN 'SẮP HẾT' ELSE 'OK' END AS CanhBao FROM ql_kho ORDER BY (SoLuongTon<=TonToiThieu) DESC,MaNL");v.addBtn("Đặt ngưỡng",()->{String ma=v.str(0);BigDecimal n=new BigDecimal(required("Ngưỡng tối thiểu",v.str(4)));if(n.signum()<0||n.scale()>3)throw new IllegalArgumentException("Ngưỡng không hợp lệ");update("UPDATE ql_kho SET TonToiThieu=? WHERE MaNL=?",n,ma);v.load();});v.addBtn("Điều chỉnh +/-",()->{String ma=v.str(0);BigDecimal delta=new BigDecimal(required("Chênh lệch (âm để giảm)","0"));if(delta.signum()==0||delta.scale()>3)throw new IllegalArgumentException("Chênh lệch không hợp lệ");String reason=required("Lý do điều chỉnh","");KhoService.giaoDich(c->{try(PreparedStatement p=c.prepareStatement("SET @kfc_reason=?")){p.setString(1,reason);p.execute();}try(PreparedStatement p=c.prepareStatement("UPDATE ql_kho SET SoLuongTon=SoLuongTon+? WHERE MaNL=? AND SoLuongTon+?>=0")){p.setBigDecimal(1,delta);p.setString(2,ma);p.setBigDecimal(3,delta);if(p.executeUpdate()!=1)throw new SQLException("Tồn không đủ");}});v.load();});add("Cảnh báo kho",v);View history=new View("SELECT ID,MaNL,ThoiGian,Truoc,Sau,Sau-Truoc AS ChenhLech,NguoiThucHien,LyDo FROM lich_su_kho ORDER BY ID DESC LIMIT 1000");add("Lịch sử kho",history);}
 private void dashboard(){View v=new View("SELECT DATE(NgayThanhToan) AS Ngay,COUNT(*) AS SoDon,SUM(TongTien) AS DoanhThu FROM hoa_don WHERE TrangThaiTT='DA_THANH_TOAN' AND NgayThanhToan>=CURRENT_DATE-INTERVAL 29 DAY GROUP BY DATE(NgayThanhToan) ORDER BY Ngay");v.addBtn("Biểu đồ 30 ngày",()->{v.load();JPanel chart=new JPanel(){protected void paintComponent(Graphics g){super.paintComponent(g);int n=v.table.getRowCount();if(n==0){g.drawString("Chưa có doanh thu",30,40);return;}double max=1;for(int i=0;i<n;i++)max=Math.max(max,((Number)v.table.getModel().getValueAt(i,2)).doubleValue());int w=Math.max(1,(getWidth()-70)/n);for(int i=0;i<n;i++){double value=((Number)v.table.getModel().getValueAt(i,2)).doubleValue();int h=(int)((getHeight()-70)*value/max);g.setColor(KfcTheme.RED);g.fillRect(35+i*w,getHeight()-35-h,Math.max(1,w-4),h);g.setColor(Color.DARK_GRAY);if(n<=12||i%5==0)g.drawString(v.table.getModel().getValueAt(i,0).toString().substring(5),35+i*w,getHeight()-15);}}};chart.setPreferredSize(new Dimension(800,360));JOptionPane.showMessageDialog(this,chart,"Doanh thu (đ)",JOptionPane.PLAIN_MESSAGE);});v.addBtn("Theo tháng/năm",()->{String unit=choose("Kỳ thống kê","Tháng","Năm");String group=unit.equals("Tháng")?"DATE_FORMAT(NgayThanhToan,'%Y-%m')":"YEAR(NgayThanhToan)";View d=new View("SELECT "+group+" AS Ky,COUNT(*) AS SoDon,SUM(TongTien) AS DoanhThu FROM hoa_don WHERE TrangThaiTT='DA_THANH_TOAN' GROUP BY "+group+" ORDER BY Ky DESC");d.load();d.addBtn("Excel",()->export(d,false));d.addBtn("PDF",()->export(d,true));d.setPreferredSize(new Dimension(720,400));JOptionPane.showMessageDialog(this,d);});v.addBtn("Top 5 món",()->{View d=new View("SELECT c.MaMon,MAX(c.TenMon) AS TenMon,SUM(c.SoLuong) AS SoLuong,SUM(c.ThanhTien) AS DoanhThu FROM chi_tiet_hoa_don c JOIN hoa_don h ON h.MaHD=c.MaHD WHERE h.TrangThaiTT='DA_THANH_TOAN' GROUP BY c.MaMon ORDER BY SoLuong DESC LIMIT 5");d.load();d.setPreferredSize(new Dimension(650,300));JOptionPane.showMessageDialog(this,d);});v.addBtn("Excel",()->export(v,false));v.addBtn("PDF",()->export(v,true));add("Dashboard doanh thu",v);}
 private void export(View v,boolean pdf)throws Exception{JFileChooser fc=new JFileChooser();fc.setSelectedFile(new File(pdf?"bao_cao.pdf":"bao_cao.xlsx"));if(fc.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;File f=fc.getSelectedFile();String ext=pdf?".pdf":".xlsx";if(!f.getName().toLowerCase().endsWith(ext))f=new File(f.getPath()+ext);if(f.exists()&&!confirm("Ghi đè file?"))return;if(pdf)kfc.utils.ReportExport.pdf(v.table.getModel(),f);else kfc.utils.ReportExport.xlsx(v.table.getModel(),f);JOptionPane.showMessageDialog(this,"Đã lưu: "+f.getAbsolutePath());}
}
